import { getLanguage } from './i18n.js';
const c=(zh,en)=>getLanguage()==='en'?en:zh;
export const lensRepo='https://github.com/ChefDavid0815/projectlens';
const release=`${lensRepo}/releases/tag/v0.1.0`;

export function lensObject(compact=false) {
  return `<div class="lens-optics${compact?' lens-optics--compact':''}" data-lens-object aria-hidden="true"><div class="lens-optics-grid"></div><div class="lens-fallback"><i></i><i></i><i></i><b>⌘</b></div><span class="lens-coordinate">X / 024<br>Y / 091</span><span class="lens-optics-caption">OPTICAL STUDY — 005</span><span class="lens-cross lens-cross--a">+</span><span class="lens-cross lens-cross--b">+</span></div>`;
}
export function lensPostArt() {
  return `<div class="post-art post-art--lens" aria-hidden="true"><div class="lens-art-meta"><span>FIELD NOTES / 008</span><span>V0.1.0</span></div><div class="lens-art-word">LOOK<br><i>CLOSER.</i></div>${lensObject(true)}<span class="lens-art-foot">A LITTLE CLARITY IN THE CODE.</span></div>`;
}
export const lensNowArt=()=>`<div class="milestone-art lens-now-art" aria-hidden="true"><div class="lens-art-meta"><span>PROJECT / 05</span><span>LOCAL FIRST</span></div><strong>LOOK<br><i>CLOSER.</i></strong>${lensObject(true)}<span class="lens-art-foot">PROJECTLENS / V0.1.0</span></div>`;
const actionLinks=()=>`<div class="lens-actions"><a class="lens-download" href="${release}" target="_blank" rel="noopener noreferrer">${c('下载 Windows 版','Get it for Windows')} <span>↓</span></a><a href="${lensRepo}" target="_blank" rel="noopener noreferrer">GitHub <span>↗</span></a><a href="./post.html?article=projectlens">${c('制作手记','Build notes')} <span>↗</span></a></div>`;
const modes=[
  ['structure','01','结构','Structure','在文件之间，发现轮廓。','Find the shape between the files.','语言、入口候选、依赖清单与目录体量，先认识项目本身。','Languages, entry candidates, manifests and directory sizes: first, understand the project.','src/ → config/ → docs/'],
  ['signals','02','线索','Signals','每一个提醒，都有来处。','Every finding has a place to begin.','检索规则、文件或描述；按严重程度筛选，展开证据与修改建议。','Search rules, files or descriptions. Filter by severity and follow the evidence and suggestions.','file:line → evidence → next step'],
  ['report','03','带走','Report','把下一步，写清楚。','Take a clearer next step.','导出 Markdown 或 JSON，把本地检查结果带进下一次整理。','Export Markdown or JSON and bring the local findings into your next round of work.','local scan → report.md / report.json']
];
export function lensCard(){return `<article class="exhibit exhibit--lens" id="project-projectlens" data-lens-mode="structure"><header class="lens-masthead"><span><b aria-hidden="true">[ / ]</b> THE LOCAL INTELLIGENCE COLLECTION</span><span>NO. 05 <i>/</i> V0.1.0</span></header><div class="lens-hero"><div class="lens-copy"><span class="lens-eyebrow"><i></i> OFFLINE BY NATURE. CURIOUS BY DESIGN.</span><h3>PROJECT<br><em>LENS<span>_</span></em></h3><p class="lens-subtitle">${c('把线索，放大。','Bring the signals into focus.')}</p><p class="lens-description">${c('一个安静的本地工作台。读懂代码、配置与文档的轮廓，再看清值得认真处理的细节。','A quiet local workspace. Read the shape of code, configuration and documentation, then look closer at the details that matter.')}</p><button class="lens-inspect" data-project="projectlens">${c('走进项目透镜','Inside ProjectLens')} <span>＋</span></button></div><div class="lens-stage">${lensObject()}<div class="lens-floating-label"><span>⌘</span><div>PROJECTLENS<small>READ-ONLY / LOCAL / EXPLAINABLE</small></div><b>↗</b></div><div class="lens-stage-edge"><span>CODE AS A LANDSCAPE</span><span>01 — 03</span></div></div></div><section class="lens-workbench" aria-label="${c('探索三项功能','Explore three capabilities')}"><div class="lens-mode-nav" role="group" aria-label="${c('功能视角','Feature perspective')}">${modes.map(([id,num,zh,en],i)=>`<button data-lens-mode-button="${id}" aria-pressed="${i===0}"><span>${num}</span>${c(zh,en)}<b>↗</b></button>`).join('')}</div><div class="lens-mode-body">${modes.map(([id,,, ,zh,en,desc,descEn,path],i)=>`<div class="lens-mode-panel" data-lens-panel="${id}"${i?' hidden':''}><div><span class="lens-eyebrow">${path}</span><h4>${c(zh,en)}</h4><p>${c(desc,descEn)}</p></div><div class="lens-mini-tree" aria-hidden="true"><div><b>⌑</b> project/</div><div>├─ src/<span>TS</span></div><div>├─ package.json<span>{ }</span></div><div>└─ README.md<span>MD</span></div></div></div>`).join('')}</div><span class="lens-demo-note">${c('功能导览 · 此展柜不会读取你的文件','FEATURE TOUR · THIS EXHIBIT DOES NOT READ YOUR FILES')}</span></section><div class="lens-specs"><span><b>LOCAL</b>${c('项目内容留在本机','Project content stays local')}</span><span><b>5 × 5</b>${c('五类规则 · 五级提示','Five categories · Five severity levels')}</span><span><b>MD / JSON</b>${c('结果清楚，也带得走','Readable. Portable.')}</span></div>${actionLinks()}<div class="lens-bottom-line"><span>WINDOWS x64 / MVP</span><span>${c('静态启发式检查 · 中文界面','Static heuristic checks · Chinese app UI')}</span><span>CHEFZC © 2026</span></div></article>`;}

export function lensDetail(){return `<div class="lens-detail"><header><span class="lens-eyebrow">LOCAL PROJECT INTELLIGENCE / V0.1.0</span><h2 id="dialog-title">ProjectLens<span>_</span></h2><p>${c('先看清项目，再决定下一步。','Understand the project. Then choose the next step.')}</p></header><figure class="lens-capture"><img src="./assets/projects/projectlens/workspace.jpg" width="1264" height="860" alt="${c('ProjectLens 原始界面，尚未选择文件夹','Actual ProjectLens interface before a folder is selected')}"><figcaption>${c('真实界面 · 浏览器渲染的桌面前端。目录扫描需要 Windows 桌面版。','Actual interface · Browser rendering of the desktop frontend. Directory scanning requires the Windows app.')}</figcaption></figure><div class="lens-detail-grid"><section><span class="lens-eyebrow">01 / FOLLOW THE SIGNAL</span><h3>${c('找到值得留意的地方','Follow what deserves attention')}</h3><p>${c('扫描代码、配置、依赖清单和文档。查看疑似凭据、维护信号、缺失的工程文件和重复代码；通过文件路径、行号、脱敏证据与建议，理解每一项提示。','Scan code, configuration, manifests and documentation. Explore possible credentials, maintenance signals, missing project foundations and duplicate code, with file paths, line numbers, redacted evidence and suggestions.')}</p></section><section><span class="lens-eyebrow">02 / CLEAR BY DESIGN</span><h3>${c('清楚，也诚实','Clear about its limits')}</h3><p>${c('这是 v0.1.0 静态规则工具，不调用远程 AI 或漏洞数据库。提示可能有误报或遗漏，不能替代编译、测试与安全审计；Windows 便携包未签名。','This v0.1.0 static-rule tool does not call remote AI or a vulnerability database. Findings can miss issues or produce false positives; they do not replace compilation, testing or security review. The Windows portable build is unsigned.')}</p></section></div>${actionLinks()}</div>`;}

export function setLensMode(button){
 const host=button.closest('.exhibit--lens');if(!host)return;
 const mode=button.dataset.lensModeButton;host.dataset.lensMode=mode;
 host.querySelectorAll('[data-lens-mode-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 host.querySelectorAll('[data-lens-panel]').forEach(p=>p.hidden=p.dataset.lensPanel!==mode);
 host.dispatchEvent(new CustomEvent('lens-mode',{bubbles:true,detail:mode}));
}
